/bin/bash -c "node --check server.js && node --check public/app.js && node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const directory = await mkdtemp(join(tmpdir(), 'reading-room-'));
process.env.BOOKS_FILE = join(directory, 'books.json');
const { createServer } = await import('./server.js');

async function start() {
  const server = createServer();
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const address = server.address();
  return { server, base: "'`http://127.0.0.1:${address.port}` };
}

try {
  let running = await start();
  let response = await fetch(`${running.base}/api/books`, { method: '"'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: 'The Left Hand of Darkness', author: 'Ursula K. Le Guin', notes: 'A favorite.' }) });
  assert.equal(response.status, 201);
  const book = await response.json();
  assert.equal(book.status, 'reading');
  response = await fetch("'`${running.base}/api/books/${book.id}`);
  assert.equal((await response.json()).notes, '"'A favorite.');
  response = await fetch("'`${running.base}/books/${book.id}`);
  assert.equal(response.status, 200);
  assert.match(await response.text(), /Reading Room/);
  response = await fetch(`${running.base}/api/books/${book.id}`, { method: '"'PATCH' });
  assert.equal((await response.json()).status, 'finished');
  await new Promise((resolve) => running.server.close(resolve));

  running = await start();
  response = await fetch("'`${running.base}/api/books`);
  const saved = await response.json();
  assert.equal(saved.length, 1);
  assert.equal(saved[0].status, '"'finished');
  assert.equal(JSON.parse(await readFile(process.env.BOOKS_FILE, 'utf8')).length, 1);
  await new Promise((resolve) => running.server.close(resolve));
  console.log('Smoke test passed: add, book route, finish, and restart persistence.');
} finally {
  await rm(directory, { recursive: true, force: true });
}
EOF

